import{_ as a,c as i,o,j as s,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const m=JSON.parse('{"title":"git-archive | x-cmd man (git man1) | Create an archive of files from a named tree","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-archive - Create an archive of files from a named tree","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-archive | x-cmd man (git man1) | Create an archive of files from a named tree"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-archive - Create an archive of files from a named tree"}]]},"headers":[],"params":{"isMan":true,"man":"git-archive","category":"git man1","desc":"Create an archive of files from a named tree"},"relativePath":"git/man1/git-archive.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-archive.md"},h={class:"visually-hidden"};function p(e,t,c,g,d,u){return o(),i("div",null,[s("h1",h,n(e.$params.man),1),t[0]||(t[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-archive - Create an archive of files from a named tree</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> archive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--format=&lt;fmt&gt;] [--list] [--prefix</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prefix</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extra</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [-o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--worktree-attributes]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [--remote</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git-upload-archive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tree-ish</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Creates an archive of the specified format containing the tree structure for the named tree, and writes it out to the standard output. If &lt;prefix&gt; is specified it is prepended to the filenames in the archive.</p><p><em>git archive</em> behaves differently when given a tree ID versus when given a commit ID or tag ID. In the first case the current time is used as the modification time of each file in the archive. In the latter case the commit time as recorded in the referenced commit object is used instead. Additionally the commit ID is stored in a global extended pax header if the tar format is used; it can be extracted using <em>git get-tar-commit-id</em>. In ZIP files it is stored as a file comment.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--format=&lt;fmt&gt;</p><blockquote><p>Format of the resulting archive. Possible values are <strong>tar</strong>, <strong>zip</strong>, <strong>tar.gz</strong>, <strong>tgz</strong>, and any format defined using the configuration option <strong>tar.&lt;format&gt;.command</strong>. If <strong>--format</strong> is not given, and the output file is specified, the format is inferred from the filename if possible (e.g. writing to <strong>foo.zip</strong> makes the output to be in the <strong>zip</strong> format). Otherwise the output format is <strong>tar</strong>.</p></blockquote><p>-l, --list</p><blockquote><p>Show all available formats.</p></blockquote><p>-v, --verbose</p><blockquote><p>Report progress to stderr.</p></blockquote><p>--prefix=&lt;prefix&gt;/</p><blockquote><p>Prepend &lt;prefix&gt;/ to paths in the archive. Can be repeated; its rightmost value is used for all tracked files. See below which value gets used by <strong>--add-file</strong> and <strong>--add-virtual-file</strong>.</p></blockquote><p>-o &lt;file&gt;, --output=&lt;file&gt;</p><blockquote><p>Write the archive to &lt;file&gt; instead of stdout.</p></blockquote><p>--add-file=&lt;file&gt;</p><blockquote><p>Add a non-tracked file to the archive. Can be repeated to add multiple files. The path of the file in the archive is built by concatenating the value of the last <strong>--prefix</strong> option (if any) before this <strong>--add-file</strong> and the basename of &lt;file&gt;.</p></blockquote><p>--add-virtual-file=&lt;path&gt;:&lt;content&gt;</p><blockquote><p>Add the specified contents to the archive. Can be repeated to add multiple files. The path of the file in the archive is built by concatenating the value of the last <strong>--prefix</strong> option (if any) before this <strong>--add-virtual-file</strong> and <strong>&lt;path&gt;</strong>.</p><p>The <strong>&lt;path&gt;</strong> argument can start and end with a literal double-quote character; the contained file name is interpreted as a C-style string, i.e. the backslash is interpreted as escape character. The path must be quoted if it contains a colon, to avoid the colon from being misinterpreted as the separator between the path and the contents, or if the path begins or ends with a double-quote character.</p><p>The file mode is limited to a regular file, and the option may be subject to platform-dependent command-line limits. For non-trivial cases, write an untracked file and use <strong>--add-file</strong> instead.</p></blockquote><p>--worktree-attributes</p><blockquote><p>Look for attributes in .gitattributes files in the working tree as well (see the section called &quot;ATTRIBUTES&quot;).</p></blockquote><p>--mtime=&lt;time&gt;</p><blockquote><p>Set modification time of archive entries. Without this option the committer time is used if <strong>&lt;tree-ish&gt;</strong> is a commit or tag, and the current time if it is a tree.</p></blockquote><p>&lt;extra&gt;</p><blockquote><p>This can be any options that the archiver backend understands. See next section.</p></blockquote><p>--remote=&lt;repo&gt;</p><blockquote><p>Instead of making a tar archive from the local repository, retrieve a tar archive from a remote repository. Note that the remote repository may place restrictions on which sha1 expressions may be allowed in <strong>&lt;tree-ish&gt;</strong>. See <strong>git-upload-archive</strong>(1) for details.</p></blockquote><p>--exec=&lt;git-upload-archive&gt;</p><blockquote><p>Used with --remote to specify the path to the <em>git-upload-archive</em> on the remote side.</p></blockquote><p>&lt;tree-ish&gt;</p><blockquote><p>The tree or commit to produce an archive for.</p></blockquote><p>&lt;path&gt;</p><blockquote><p>Without an optional path parameter, all files and subdirectories of the current working directory are included in the archive. If one or more paths are specified, only these are included.</p></blockquote><h2 id="backend-extra-options" tabindex="-1">BACKEND EXTRA OPTIONS <a class="header-anchor" href="#backend-extra-options" aria-label="Permalink to &quot;BACKEND EXTRA OPTIONS&quot;">​</a></h2><h3 id="zip" tabindex="-1">zip <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;zip&quot;">​</a></h3><p>-&lt;digit&gt;</p><blockquote><p>Specify compression level. Larger values allow the command to spend more time to compress to smaller size. Supported values are from <strong>-0</strong> (store-only) to <strong>-9</strong> (best ratio). Default is <strong>-6</strong> if not given.</p></blockquote><h3 id="tar" tabindex="-1">tar <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;tar&quot;">​</a></h3><p>-&lt;number&gt;</p><blockquote><p>Specify compression level. The value will be passed to the compression command configured in <strong>tar.&lt;format&gt;.command</strong>. See manual page of the configured command for the list of supported levels and the default level if this option isn&#39;t specified.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>tar.umask</p><blockquote><p>This variable can be used to restrict the permission bits of tar archive entries. The default is 0002, which turns off the world write bit. The special value &quot;user&quot; indicates that the archiving user&#39;s umask will be used instead. See umask(2) for details. If <strong>--remote</strong> is used then only the configuration of the remote repository takes effect.</p></blockquote><p>tar.&lt;format&gt;.command</p><blockquote><p>This variable specifies a shell command through which the tar output generated by <strong>git archive</strong> should be piped. The command is executed using the shell with the generated tar file on its standard input, and should produce the final output on its standard output. Any compression-level options will be passed to the command (e.g., <strong>-9</strong>).</p><p>The <strong>tar.gz</strong> and <strong>tgz</strong> formats are defined automatically and use the magic command <strong>git archive gzip</strong> by default, which invokes an internal implementation of gzip.</p></blockquote><p>tar.&lt;format&gt;.remote</p><blockquote><p>If true, enable the format for use by remote clients via <strong>git-upload-archive</strong>(1). Defaults to false for user-defined formats, but true for the <strong>tar.gz</strong> and <strong>tgz</strong> formats.</p></blockquote><h2 id="attributes" tabindex="-1">ATTRIBUTES <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;ATTRIBUTES&quot;">​</a></h2><p>export-ignore</p><blockquote><p>Files and directories with the attribute export-ignore won&#39;t be added to archive files. See <strong>gitattributes</strong>(5) for details.</p></blockquote><p>export-subst</p><blockquote><p>If the attribute export-subst is set for a file then Git will expand several placeholders when adding this file to an archive. See <strong>gitattributes</strong>(5) for details.</p></blockquote><p>Note that attributes are by default taken from the <strong>.gitattributes</strong> files in the tree that is being archived. If you want to tweak the way the output is generated after the fact (e.g. you committed without adding an appropriate export-ignore in its <strong>.gitattributes</strong>), adjust the checked out <strong>.gitattributes</strong> file as necessary and use <strong>--worktree-attributes</strong> option. Alternatively you can keep necessary attributes that should apply while archiving any tree in your <strong>$GIT_DIR/info/attributes</strong> file.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p><strong>git archive --format=tar --prefix=junk/ HEAD | (cd /var/tmp/ &amp;&amp; tar xf -)</strong></p><blockquote><p>Create a tar archive that contains the contents of the latest commit on the current branch, and extract it in the <strong>/var/tmp/junk</strong> directory.</p></blockquote><p><strong>git archive --format=tar --prefix=git-1.4.0/ v1.4.0 | gzip &gt;git-1.4.0.tar.gz</strong></p><blockquote><p>Create a compressed tarball for v1.4.0 release.</p></blockquote><p><strong>git archive --format=tar.gz --prefix=git-1.4.0/ v1.4.0 &gt;git-1.4.0.tar.gz</strong></p><blockquote><p>Same as above, but using the builtin tar.gz handling.</p></blockquote><p><strong>git archive --prefix=git-1.4.0/ -o git-1.4.0.tar.gz v1.4.0</strong></p><blockquote><p>Same as above, but the format is inferred from the output file.</p></blockquote><p><strong>git archive --format=tar --prefix=git-1.4.0/ v1.4.0^{tree} | gzip &gt;git-1.4.0.tar.gz</strong></p><blockquote><p>Create a compressed tarball for v1.4.0 release, but without a global extended pax header.</p></blockquote><p><strong>git archive --format=zip --prefix=git-docs/ HEAD:Documentation/ &gt; git-1.4.0-docs.zip</strong></p><blockquote><p>Put everything in the current head&#39;s Documentation/ directory into <em>git-1.4.0-docs.zip</em>, with the prefix <em>git-docs/</em>.</p></blockquote><p><strong>git archive -o latest.zip HEAD</strong></p><blockquote><p>Create a Zip archive that contains the contents of the latest commit on the current branch. Note that the output format is inferred by the extension of the output file.</p></blockquote><p><strong>git archive -o latest.tar --prefix=build/ --add-file=configure --prefix= HEAD</strong></p><blockquote><p>Creates a tar archive that contains the contents of the latest commit on the current branch with no prefix and the untracked file <em>configure</em> with the prefix <em>build/</em>.</p></blockquote><p><strong>git config tar.tar.xz.command &quot;xz -c&quot;</strong></p><blockquote><p>Configure a &quot;tar.xz&quot; format for making LZMA-compressed tarfiles. You can use it specifying <strong>--format=tar.xz</strong>, or by creating an output file like <strong>-o foo.tar.xz</strong>.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitattributes</strong>(5)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,79))])}const k=a(l,[["render",p]]);export{m as __pageData,k as default};
